// ── Edição de texto ───────────────────────────────────────────────────────
function edit({ text, caret }, op) {
  const before = text.slice(0, caret), after = text.slice(caret);
  const wordStart = before.length - (before.match(/\S+\s*$|\s+$/)?.[0].length ?? 0);
  const wordEnd = caret + (after.match(/^\s*\S+/)?.[0].length ?? after.length);
  switch (op) {
    case 'newline': return { text: `${before}\n${after}`, caret: caret + 1 };
    case 'back': return caret ? { text: before.slice(0, -1) + after, caret: caret - 1 } : null;
    case 'del': return { text: before + after.slice(1), caret };
    case 'wordBack': return { text: before.slice(0, wordStart) + after, caret: wordStart };
    case 'lineBack': return { text: after, caret: 0 };
    case 'left': return { text, caret: Math.max(0, caret - 1) };
    case 'right': return { text, caret: Math.min(text.length, caret + 1) };
    case 'wordLeft': return { text, caret: wordStart };
    case 'wordRight': return { text, caret: wordEnd };
    case 'home': return { text, caret: 0 };
    case 'end': return { text, caret: text.length };
    case 'clear': return { text: '', caret: 0 };
    default: return null;
  }
}

