// Cópia de dados puros: o estado só tem objetos simples, arrays e primitivos. É bem mais barata que structuredClone,
// que serializa num buffer e gera lixo a cada tecla.
const copy = v => {
  if (Array.isArray(v)) { const a = new Array(v.length); for (let i = 0; i < v.length; i++) a[i] = copy(v[i]); return a; }
  if (v && typeof v === 'object') { const o = {}; for (const k in v) o[k] = copy(v[k]); return o; }
  return v;
};

// Desfazer: a cada ação de usuário que muda o domínio, o store anterior (imutável) vai para a pilha, até 30.
// Ação confirmada é barreira: o que pediu confirmação é externo ou irreversível e não se desfaz localmente.
const EDITS = new Set(['OP', 'ACT', 'PKEY', 'ACTIVATE', 'SUBMIT', 'OV_ACCEPT', 'MENTION', 'NOTICE', 'SIDE_KEY', 'COMPLETE_PATH']);
const PASSIVE = new Set(['TICK', 'PATCH_SETTINGS', 'PATCH']);
let depth = 0;
function track(S, out, a) {
  if (a.type === 'UNDO' || a.type === 'REDO') return;
  if (a.type === 'CONFIRM' || (a.type === 'OV_ACCEPT' && S.overlay?.kind === 'confirm')) { out.undo = []; out.redo = []; return; }
  if (!EDITS.has(a.type) || JSON.stringify(out.store) === JSON.stringify(S.store)) return;
  out.undo = [...(S.undo ?? []), { store: S.store, label: out.ui.toast }].slice(-30);
  out.redo = [];
  out.ui.toast = `${out.ui.toast || 'feito'} · ⌘Z desfaz`;
}

export function reduce(S, a) {
  if (!a || typeof a !== 'object' || !H[a.type]) return S;
  const top = depth === 0;
  const n = copy({ ...S, undo: null, redo: null });
  n.undo = S.undo ?? []; n.redo = S.redo ?? []; // os snapshots são imutáveis: não precisam de cópia
  if (top && !PASSIVE.has(a.type)) n.ui.toast = null; // o aviso some na próxima ação
  depth++;
  try {
    const result = H[a.type](n, a);
    if (result === false) return S;
    const out = Array.isArray(result) ? result.reduce(reduce, n) : n;
    if (top) {
      track(S, out, a);
      const was = S.tabs.length && focused(S).id, now = out.tabs.length && focused(out).id;
      if (was && now && was !== now) out.ui.lastPane = was; // ⌘' volta para a última folha com foco
      if (now && focused(out).data.unread) focused(out).data.unread = false; // olhar a folha marca como lido
    }
    return out;
  } finally { depth--; }
}

export { ctxOf };
